import{_ as p,l as i,o as e,c as s,v as t,p as l,x as r,d as n,i as c,S as d}from"./chunks/framework.InCnrqk-.js";const B=JSON.parse('{"title":"Multi-Paxos","description":"","frontmatter":{"title":"Multi-Paxos","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/multi-paxos.md","filePath":"cs/multi-paxos.md","lastUpdated":1789023840000}'),m={name:"cs/multi-paxos.md"};function h(u,a,x,P,_,E){const o=i("Mermaid");return e(),s("div",null,[a[1]||(a[1]=t('<h1 id="multi-paxos" tabindex="-1">Multi-Paxos <a class="header-anchor" href="#multi-paxos" aria-label="Permalink to &quot;Multi-Paxos&quot;">​</a></h1><div class="epigraph"><p>同一领导者把 prepare 摊到整个任期：每个日志槽只跑 accept。稳定主把两轮变成一轮，直到主被怀疑。</p><footer>—— 据 Lamport, Paxos Made Simple, 2001；Chandra, Griesemer and Redstone, Paxos Made Live, PODC 2007 整理</footer></div><p>上一课<a href="/cs/paxos">Paxos</a>每个值两轮 RPC。RSM 每条命令都付两轮则延迟翻倍。缺口是<strong>跨槽复用承诺</strong>：领导者先对「我以编号 \\(n\\) 统治后续槽」做一次 prepare，然后只对每个槽 accept。本课不重证相交。后课 Raft 用术语 term/log 把同一形状讲得更像实现。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Basic Paxos 的 prepare 返回「该槽已接受值」。若领导者连任，空槽没有已接受值，prepare 只为占编号。把编号改成任期：一次 prepare（或选举）覆盖无穷槽，接受者为该任期承诺。之后客户端命令直接 accept 到槽 \\(i,i+1,\\ldots\\)。</p><p>缺口：领导者不知道哪些槽已有空洞。Paxos Made Live：用状态机 + 日志压缩 + 磁盘、流控、以及「主必须把空洞填无操作」。活锁变成选举抖动。</p><p><span class="marginnote">Lamport 在 <em>Made Simple</em> 末节点出稳定领导者。Google Chubby 背后的 Paxos Made Live 把工程税写全：磁盘、多线程、问题成员。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>选举：想当主的节点用更高任期跑一遍 prepare 范围，收集各槽已有值，把自己日志对齐到「可能已选定」的前缀，再对外服务。接受：槽号 + 任期 + 命令。提交：多数派 accept 后可 apply——提交点是连续前缀，空洞不许跳着提交。</p>',9)),(e(),l(d,null,{default:r(()=>[c(o,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20EL%5B%22%E4%B8%80%E6%AC%A1%20prepare%20%2F%20%E9%80%89%E4%B8%BE%22%5D%20--%3E%20TERM%5B%22%E4%BB%BB%E6%9C%9F%20n%22%5D%0A%20%20TERM%20--%3E%20ACC%5B%22%E6%AF%8F%E6%A7%BD%E4%B8%80%E8%BD%AE%20accept%22%5D%0A%20%20ACC%20--%3E%20PREF%5B%22%E8%BF%9E%E7%BB%AD%E5%B7%B2%E6%8F%90%E4%BA%A4%E5%89%8D%E7%BC%80%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>与主备：Multi-Paxos 的主是日志领导者，备是接受者；fencing 就是更高任期使旧 accept 被拒。这把<a href="/cs/primary-backup-failover">主备切换</a>的纪元钉成 Paxos 编号。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>读优化：领导者若有租约（上一单元），可本地读，否则 read index 向多数派确认自己仍主。无租约时本地读不是线性一致。写延迟：连通且稳定主时一轮多数派 RTT。</p><p>成员尚未变：本课固定 \\(n\\)。配置变更是后课 Raft 更愿意讲的缺口，Paxos 用 α 配置或联合多数派，点名即可。</p><p>本课不把「Multi-Paxos」当成与 Basic 不同的安全理论：安全仍是每槽 Basic。工程差在日志、空洞、磁盘与主稳定性。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写 Raft 的选举超时公式，不引入 Zab 纪元。后课默认：生产用的 Paxos 是 Multi 形状；看到两轮 prepare/accept 是单槽或主不稳。Raft 下一课用更强的日志匹配规则降低实现歧义。</p><p>一轮 accept 是优化，不是新的不可能逃逸。主一抖，prepare 税回来。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>稳定领导者：每槽一轮 accept；prepare 按任期摊销。</li><li>提交必须是无空洞前缀。</li><li>旧主靠更高任期 fencing。</li><li>出处：Lamport, 2001；Chandra, Griesemer and Redstone, PODC 2007。</li></ul>',10))])}const A=p(m,[["render",h]]);export{B as __pageData,A as default};
